1	{
2	  "name": "stockroom",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  },
12	  "bin": {
13	    "stockroom": "app.ts"
14	  }
15	}
16

1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType =
17	  | DocType
18	  | 'count'
19	  | 'arrival'
20	  | 'return'
21	  | 'in-rev'
22	  | 'out-rev'
23	  | 'transfer-rev'
24	  | 'count-rev'
25	  | 'arrival-rev'
26	  | 'return-rev';
27	
28	interface LedgerEntry {
29	  seq: number; // 全局流水序号，即提交顺序
30	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
31	  type: EntryType;
32	  product: string;
33	  wh: string; // 本流水条目变动余量的仓库（到货为采购单收货仓）
34	  qty?: number; // 入库/出库/调拨/到货类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
35	  before: number;
36	  after: number;
37	  from?: string; // 调拨（或冲销调拨）的调出仓
38	  to?: string; // 调拨（或冲销调拨）的调入仓
39	  po?: string; // 到货/退货流水：所属采购单编号
40	  arr?: string; // 退货（及冲销退货）流水：原到货单编号
41	  orig?: string; // 冲销流水：被冲销的原单编号
42	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
43	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
44	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
45	}
46	
47	interface DocRecord {
48	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
49	  resultLines: string[]; // 原提交结果，供幂等重放
50	}
51	
52	interface ReversalRecord {
53	  orig: string; // 被冲销的原单编号
54	  resultLines: string[]; // 冲销提交结果，供幂等重放
55	}
56	
57	interface PurchaseRecord {
58	  poId: string;
59	  supplier: string;
60	  wh: string; // 收货仓
61	  ordered: Record<string, number>; // 商品 -> 订购量（合并后，正安全整数）
62	  resultLines: string[]; // 登记结果，供幂等重放
63	}
64	
65	interface ArrivalRecord {
66	  poId: string; // 所属采购单
67	  wh: string; // 采购单收货仓（冗余自采购单，便于校验与展示）
68	  qty: Record<string, number>; // 本次到货：商品 -> 数量（合并后，正安全整数）
69	  resultLines: string[]; // 到货提交结果，供幂等重放
70	}
71	
72	interface CancelRecord {
73	  poId: string; // 所属采购单
74	  qty: Record<string, number>; // 本次取消：商品 -> 数量（合并后，正安全整数）
75	  resultLines: string[]; // 取消提交结果，供幂等重放
76	}
77	
78	interface ReturnRecord {
79	  arrId: string; // 原到货单编号
80	  poId: string; // 所属采购单（冗余自原到货单，便于校验与展示）
81	  wh: string; // 原到货单收货仓（退货从该仓当前余量扣减）
82	  qty: Record<string, number>; // 本次退货：商品 -> 数量（合并后，正安全整数）
83	  resultLines: string[]; // 退货提交结果，供幂等重放
84	}
85	
86	interface Store {
87	  version: 1;
88	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
89	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
90	  entries: LedgerEntry[];
91	  docs: Record<string, DocRecord>; // 入库/出库/调拨/盘点单去重与结果
92	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果（可冲销到货单、取消单、退货单）
93	  purchases: Record<string, PurchaseRecord>; // 采购单登记（独立编号空间，不改库存）
94	  arrivals: Record<string, ArrivalRecord>; // 到货单去重与结果（与库存单共用编号空间）
95	  cancels: Record<string, CancelRecord>; // 取消单去重与结果（与库存单共用编号空间，不改库存与流水）
96	  returns: Record<string, ReturnRecord>; // 退货单去重与结果（与库存单共用编号空间）
97	}
98	
99	const REV_ENTRY_TYPES = new Set<EntryType>([
100	  'in-rev', 'out-rev', 'transfer-rev', 'count-rev', 'arrival-rev', 'return-rev',
101	]);
102	
103	function nullProto<T extends object>(): T {
104	  return Object.create(null) as T;
105	}
106	
107	function emptyStore(): Store {
108	  return {
109	    version: 1,
110	    products: nullProto(),
111	    stock: nullProto(),
112	    entries: [],
113	    docs: nullProto(),
114	    reversals: nullProto(),
115	    purchases: nullProto(),
116	    arrivals: nullProto(),
117	    cancels: nullProto(),
118	    returns: nullProto(),
119	  };
120	}
121	
122	// ---------- 工具 ----------
123	
124	function isPlainObject(v: unknown): v is Record<string, unknown> {
125	  return typeof v === 'object' && v !== null && !Array.isArray(v);
126	}
127	
128	function isNonNegSafeInt(v: unknown): v is number {
129	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
130	}
131	
132	function isPosSafeInt(v: unknown): v is number {
133	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
134	}
135	
136	function trimOrThrow(label: string, raw: string): string {
137	  const s = raw.trim();
138	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
139	  return s;
140	}
141	
142	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
143	function stableStringify(v: unknown): string {
144	  if (isPlainObject(v)) {
145	    return (
146	      '{' +
147	      Object.keys(v)
148	        .sort()
149	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
150	        .join(',') +
151	      '}'
152	    );
153	  }
154	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
155	  return JSON.stringify(v);
156	}
157	
158	// ---------- 数据持久化 ----------
159	
160	function dataPath(dataDir: string): string {
161	  return join(dataDir, DATA_FILENAME);
162	}
163	
164	function loadStore(dataDir: string): Store {
165	  let raw: string;
166	  try {
167	    raw = readFileSync(dataPath(dataDir), 'utf8');
168	  } catch (e) {
169	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
170	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
171	  }
172	
173	  let data: unknown;
174	  try {
175	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
176	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
177	    data = JSON.parse(raw);
178	  } catch {
179	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
180	  }
181	  return validateStore(data);
182	}
183	
184	function validateStore(data: unknown): Store {
185	  const bad = (msg: string): DataError =>
186	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
187	
188	  if (!isPlainObject(data)) throw bad('根节点不是对象');
189	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
190	
191	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
192	  const store = emptyStore();
193	
194	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
195	  for (const [id, name] of Object.entries(data.products)) {
196	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
197	      throw bad('products 中存在非法编号或名称');
198	    store.products[id] = name;
199	  }
200	
201	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
202	  for (const [pid, whs] of Object.entries(data.stock)) {
203	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
204	    const whMap = nullProto<Record<string, number>>();
205	    for (const [wh, qty] of Object.entries(whs)) {
206	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
207	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
208	      whMap[wh] = qty;
209	    }
210	    store.stock[pid] = whMap;
211	  }
212	
213	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
214	  let lastSeq = 0;
215	  for (const e of data.entries as unknown[]) {
216	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
217	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
218	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
219	    const isRev = REV_ENTRY_TYPES.has(e.type as EntryType);
220	    const isOrig =
221	      e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count' ||
222	      e.type === 'arrival' || e.type === 'return';
223	    if (!isRev && !isOrig) throw bad('流水类型非法');
224	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
225	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
226	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
227	    if (e.type === 'count' || e.type === 'count-rev') {
228	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
229	        throw bad('盘点流水账面/实盘量非法');
230	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
231	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
232	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
233	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
234	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined || e.po !== undefined ||
235	          e.arr !== undefined)
236	        throw bad('盘点流水不应携带数量、调拨、采购或退货字段');
237	    } else {
238	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
239	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
240	        throw bad('非盘点流水不应携带盘点字段');
241	      const delta = e.after - e.before;
242	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
243	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
244	          throw bad('调拨流水缺少调出/调入仓');
245	        if (e.po !== undefined || e.arr !== undefined) throw bad('调拨流水不应携带采购或退货字段');
246	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
247	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
248	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
249	      } else {
250	        if (e.from !== undefined || e.to !== undefined) throw bad('非调拨流水不应携带调拨字段');
251	        // 到货入收货仓、冲销退货补回为增；退货从收货仓扣减、冲销到货扣回为减
252	        const increases =
253	          e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev';
254	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
255	        if (e.type === 'arrival' || e.type === 'arrival-rev') {
256	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('到货流水缺少采购单编号');
257	          if (e.arr !== undefined) throw bad('到货流水不应携带原到货单字段');
258	        } else if (e.type === 'return' || e.type === 'return-rev') {
259	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('退货流水缺少采购单编号');
260	          if (typeof e.arr !== 'string' || e.arr.trim() === '') throw bad('退货流水缺少原到货单编号');
261	        } else if (e.po !== undefined || e.arr !== undefined) {
262	          throw bad('非到货/退货流水不应携带采购或退货字段');
263	        }
264	      }
265	    }
266	    if (isRev) {
267	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
268	    } else if (e.orig !== undefined) {
269	      throw bad('原始单据流水不应携带冲销标记');
270	    }
271	    store.entries.push(e as unknown as LedgerEntry);
272	  }
273	
274	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
275	  for (const [docId, rec] of Object.entries(data.docs)) {
276	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
277	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
278	      throw bad(`单据 ${docId} 的去重记录非法`);
279	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
280	    const c = rec.content;
281	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
282	      throw bad(`单据 ${docId} 的业务类型非法`);
283	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
284	    for (const [pid, item] of Object.entries(c.items)) {
285	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
286	      if (c.type === 'count') {
287	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
288	          throw bad(`单据 ${docId} 存在非法盘点明细`);
289	      } else if (!isPosSafeInt(item)) {
290	        throw bad(`单据 ${docId} 存在非法明细`);
291	      }
292	    }
293	    if (c.type === 'transfer') {
294	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
295	        throw bad(`单据 ${docId} 的调拨仓非法`);
296	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
297	      throw bad(`单据 ${docId} 的仓库非法`);
298	    }
299	    store.docs[docId] = rec as unknown as DocRecord;
300	  }
301	
302	  // purchases 为新增字段：合法旧数据没有该字段，按空集合处理。
303	  // 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名。
304	  if (data.purchases !== undefined) {
305	    if (!isPlainObject(data.purchases)) throw bad('purchases 不是对象');
306	    for (const [poId, rec] of Object.entries(data.purchases)) {
307	      if (typeof poId !== 'string' || poId.trim() === '') throw bad('存在非法采购单编号');
308	      if (
309	        !isPlainObject(rec) ||
310	        typeof rec.supplier !== 'string' || rec.supplier.trim() === '' ||
311	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
312	        !isPlainObject(rec.ordered) ||
313	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
314	      )
315	        throw bad(`采购单 ${poId} 的记录非法`);
316	      if (rec.poId !== undefined && rec.poId !== poId) throw bad(`采购单 ${poId} 的内嵌编号不一致`);
317	      const ordered = nullProto<Record<string, number>>();
318	      for (const [pid, qty] of Object.entries(rec.ordered)) {
319	        if (pid.trim() === '' || !isPosSafeInt(qty)) throw bad(`采购单 ${poId} 存在非法订购明细`);
320	        ordered[pid] = qty;
321	      }
322	      if (Object.keys(ordered).length === 0) throw bad(`采购单 ${poId} 至少需要一种商品`);
323	      store.purchases[poId] = {
324	        poId, supplier: rec.supplier, wh: rec.wh, ordered, resultLines: rec.resultLines,
325	      };
326	    }
327	  }
328	
329	  // arrivals 为新增字段：合法旧数据没有该字段，按空集合处理。
330	  // 到货单与入库/出库/调拨/盘点/冲销单共用全局唯一编号空间。
331	  if (data.arrivals !== undefined) {
332	    if (!isPlainObject(data.arrivals)) throw bad('arrivals 不是对象');
333	    for (const [arrId, rec] of Object.entries(data.arrivals)) {
334	      if (typeof arrId !== 'string' || arrId.trim() === '') throw bad('存在非法到货单编号');
335	      if (store.docs[arrId] !== undefined) throw bad(`到货单编号 ${arrId} 与原始库存单据编号冲突`);
336	      if (
337	        !isPlainObject(rec) ||
338	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
339	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
340	        !isPlainObject(rec.qty) ||
341	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
342	      )
343	        throw bad(`到货单 ${arrId} 的记录非法`);
344	      const qty = nullProto<Record<string, number>>();
345	      for (const [pid, q] of Object.entries(rec.qty)) {
346	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`到货单 ${arrId} 存在非法到货明细`);
347	        qty[pid] = q;
348	      }
349	      if (Object.keys(qty).length === 0) throw bad(`到货单 ${arrId} 至少需要一种商品`);
350	      const po = store.purchases[rec.poId];
351	      if (po === undefined) throw bad(`到货单 ${arrId} 指向的采购单 ${rec.poId} 不存在`);
352	      if (rec.wh !== po.wh) throw bad(`到货单 ${arrId} 的收货仓与采购单 ${rec.poId} 不一致`);
353	      for (const [pid, q] of Object.entries(qty)) {
354	        if (po.ordered[pid] === undefined)
355	          throw bad(`到货单 ${arrId} 含采购单 ${rec.poId} 未订购的商品 ${pid}`);
356	        if (q > po.ordered[pid])
357	          throw bad(`到货单 ${arrId} 商品 ${pid} 到货量超过订购量`);
358	      }
359	      store.arrivals[arrId] = { poId: rec.poId, wh: rec.wh, qty, resultLines: rec.resultLines };
360	    }
361	  }
362	
363	  // cancels 为新增字段：合法旧数据没有该字段，按空集合处理。
364	  // 取消单与入库/出库/调拨/盘点/到货/冲销单共用全局唯一编号空间；
365	  // 取消只减少待收承诺，不改库存、不产生库存流水。
366	  if (data.cancels !== undefined) {
367	    if (!isPlainObject(data.cancels)) throw bad('cancels 不是对象');
368	    for (const [canId, rec] of Object.entries(data.cancels)) {
369	      if (typeof canId !== 'string' || canId.trim() === '') throw bad('存在非法取消单编号');
370	      if (store.docs[canId] !== undefined) throw bad(`取消单编号 ${canId} 与原始库存单据编号冲突`);
371	      if (store.arrivals[canId] !== undefined) throw bad(`取消单编号 ${canId} 与到货单编号冲突`);
372	      if (
373	        !isPlainObject(rec) ||
374	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
375	        !isPlainObject(rec.qty) ||
376	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
377	      )
378	        throw bad(`取消单 ${canId} 的记录非法`);
379	      const qty = nullProto<Record<string, number>>();
380	      for (const [pid, q] of Object.entries(rec.qty)) {
381	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`取消单 ${canId} 存在非法取消明细`);
382	        qty[pid] = q;
383	      }
384	      if (Object.keys(qty).length === 0) throw bad(`取消单 ${canId} 至少需要一种商品`);
385	      const po = store.purchases[rec.poId];
386	      if (po === undefined) throw bad(`取消单 ${canId} 指向的采购单 ${rec.poId} 不存在`);
387	      for (const [pid, q] of Object.entries(qty)) {
388	        if (po.ordered[pid] === undefined)
389	          throw bad(`取消单 ${canId} 含采购单 ${rec.poId} 未订购的商品 ${pid}`);
390	        if (q > po.ordered[pid])
391	          throw bad(`取消单 ${canId} 商品 ${pid} 取消量超过订购量`);
392	      }
393	      store.cancels[canId] = { poId: rec.poId, qty, resultLines: rec.resultLines };
394	    }
395	  }
396	
397	  // returns 为新增字段：合法旧数据没有该字段，按无退货处理。
398	  // 退货单与入库/出库/调拨/盘点/到货/取消/冲销单共用全局唯一编号空间；
399	  // 退货引用一张原到货单，采购单与收货仓取原到货，只退原到货明细内商品。
400	  if (data.returns !== undefined) {
401	    if (!isPlainObject(data.returns)) throw bad('returns 不是对象');
402	    for (const [retId, rec] of Object.entries(data.returns)) {
403	      if (typeof retId !== 'string' || retId.trim() === '') throw bad('存在非法退货单编号');
404	      if (store.docs[retId] !== undefined) throw bad(`退货单编号 ${retId} 与原始库存单据编号冲突`);
405	      if (store.arrivals[retId] !== undefined) throw bad(`退货单编号 ${retId} 与到货单编号冲突`);
406	      if (store.cancels[retId] !== undefined) throw bad(`退货单编号 ${retId} 与取消单编号冲突`);
407	      if (
408	        !isPlainObject(rec) ||
409	        typeof rec.arrId !== 'string' || rec.arrId.trim() === '' ||
410	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
411	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
412	        !isPlainObject(rec.qty) ||
413	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
414	      )
415	        throw bad(`退货单 ${retId} 的记录非法`);
416	      const qty = nullProto<Record<string, number>>();
417	      for (const [pid, q] of Object.entries(rec.qty)) {
418	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`退货单 ${retId} 存在非法退货明细`);
419	        qty[pid] = q;
420	      }
421	      if (Object.keys(qty).length === 0) throw bad(`退货单 ${retId} 至少需要一种商品`);
422	      const arr = store.arrivals[rec.arrId];
423	      if (arr === undefined) throw bad(`退货单 ${retId} 指向的原到货单 ${rec.arrId} 不存在`);
424	      if (rec.poId !== arr.poId) throw bad(`退货单 ${retId} 的采购单与原到货单 ${rec.arrId} 不一致`);
425	      if (rec.wh !== arr.wh) throw bad(`退货单 ${retId} 的收货仓与原到货单 ${rec.arrId} 不一致`);
426	      for (const [pid, q] of Object.entries(qty)) {
427	        if (arr.qty[pid] === undefined)
428	          throw bad(`退货单 ${retId} 含原到货单 ${rec.arrId} 没有的商品 ${pid}`);
429	        if (q > arr.qty[pid]) throw bad(`退货单 ${retId} 商品 ${pid} 退货量超过原到货量`);
430	      }
431	      store.returns[retId] = { arrId: rec.arrId, poId: rec.poId, wh: rec.wh, qty, resultLines: rec.resultLines };
432	    }
433	  }
434	
435	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理。
436	  // 原单既可以是入库/出库/调拨/盘点单，也可以是到货单、取消单、退货单；冲销单不可冲销。
437	  if (data.reversals !== undefined) {
438	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
439	    for (const [revId, rec] of Object.entries(data.reversals)) {
440	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
441	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
442	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
443	        throw bad(`冲销单 ${revId} 的记录非法`);
444	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始库存单据编号冲突`);
445	      if (store.arrivals[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与到货单编号冲突`);
446	      if (store.cancels[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与取消单编号冲突`);
447	      if (store.returns[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与退货单编号冲突`);
448	      const origRec = store.docs[rec.orig];
449	      const origArr = store.arrivals[rec.orig];
450	      const origCan = store.cancels[rec.orig];
451	      const origRet = store.returns[rec.orig];
452	      if (origRec === undefined && origArr === undefined && origCan === undefined && origRet === undefined) {
453	        // 用 data.reversals 判定，避免依赖键的先后顺序（此时 store.reversals 可能尚未装全）
454	        if (isPlainObject((data.reversals as Record<string, unknown>)[rec.orig]))
455	          throw bad(`冲销单 ${rec.orig} 不可被再次冲销（冲销单不能冲销冲销单）`);
456	        if (store.purchases[rec.orig] !== undefined)
457	          throw bad(`冲销单 ${revId} 指向的 ${rec.orig} 是采购单，采购单不可冲销`);
458	        throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
459	      }
460	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
461	    }
462	    // 每张原单最多被成功冲销一次（库存单与到货单统一校验）
463	    const origSeen = nullProto<Record<string, string>>();
464	    for (const [revId, rec] of Object.entries(store.reversals)) {
465	      if (origSeen[rec.orig] !== undefined)
466	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
467	      origSeen[rec.orig] = revId;
468	    }
469	    // 冲销单不可冲销：冲销关系不能指向另一张冲销单
470	    for (const rec of Object.values(store.reversals)) {
471	      if (store.reversals[rec.orig] !== undefined)
472	        throw bad(`冲销单 ${rec.orig} 不可被再次冲销`);
473	    }
474	    // 冲销流水必须能找到所属冲销单
475	    for (const e of store.entries) {
476	      if (REV_ENTRY_TYPES.has(e.type) && store.reversals[e.doc] === undefined)
477	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
478	    }
479	  }
480	
481	  // 到货流水必须能找到所属到货单，且逐项数量/采购单/收货仓与记录一致
482	  const arrivalEntrySeen = nullProto<Record<string, Record<string, number>>>();
483	  for (const e of store.entries) {
484	    if (e.type !== 'arrival') continue;
485	    const arr = store.arrivals[e.doc];
486	    if (arr === undefined) throw bad(`流水引用了不存在的到货单 ${e.doc}`);
487	    if (e.po !== arr.poId) throw bad(`到货单 ${e.doc} 流水的采购单编号与记录不一致`);
488	    if (e.wh !== arr.wh) throw bad(`到货单 ${e.doc} 流水的收货仓与记录不一致`);
489	    const perProduct = (arrivalEntrySeen[e.doc] ??= nullProto<Record<string, number>>());
490	    perProduct[e.product] = (perProduct[e.product] ?? 0) + e.qty!;
491	  }
492	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
493	    const seen = arrivalEntrySeen[arrId];
494	    if (seen === undefined) throw bad(`到货单 ${arrId} 缺少到货流水`);
495	    for (const [pid, q] of Object.entries(arr.qty)) {
496	      if (seen[pid] !== q) throw bad(`到货单 ${arrId} 商品 ${pid} 的流水数量与记录不一致`);
497	    }
498	    for (const pid of Object.keys(seen)) {
499	      if (arr.qty[pid] === undefined) throw bad(`到货单 ${arrId} 的流水含记录中没有的商品 ${pid}`);
500	    }
501	  }
502	
503	  // 冲销到货流水逐项数量必须与原到货单一致
504	  for (const e of store.entries) {
505	    if (e.type !== 'arrival-rev') continue;
506	    const rev = store.reversals[e.doc];
507	    if (rev === undefined) throw bad(`冲销到货流水引用了不存在的冲销单 ${e.doc}`);
508	    const arr = store.arrivals[rev.orig];
509	    if (arr === undefined) throw bad(`冲销单 ${e.doc} 指向的到货原单 ${rev.orig} 不存在`);
510	    if (e.po !== arr.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原到货单不一致`);
511	    if (arr.qty[e.product] !== e.qty)
512	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原到货单不一致`);
513	  }
514	
515	  // 退货流水必须能找到所属退货单，且逐项数量/原到货单/采购单/收货仓与记录一致
516	  const returnEntrySeen = nullProto<Record<string, Record<string, number>>>();
517	  for (const e of store.entries) {
518	    if (e.type !== 'return') continue;
519	    const ret = store.returns[e.doc];
520	    if (ret === undefined) throw bad(`流水引用了不存在的退货单 ${e.doc}`);
521	    if (e.arr !== ret.arrId) throw bad(`退货单 ${e.doc} 流水的原到货单编号与记录不一致`);
522	    if (e.po !== ret.poId) throw bad(`退货单 ${e.doc} 流水的采购单编号与记录不一致`);
523	    if (e.wh !== ret.wh) throw bad(`退货单 ${e.doc} 流水的收货仓与记录不一致`);
524	    const perProduct = (returnEntrySeen[e.doc] ??= nullProto<Record<string, number>>());
525	    perProduct[e.product] = (perProduct[e.product] ?? 0) + e.qty!;
526	  }
527	  for (const [retId, ret] of Object.entries(store.returns)) {
528	    const seen = returnEntrySeen[retId];
529	    if (seen === undefined) throw bad(`退货单 ${retId} 缺少退货流水`);
530	    for (const [pid, q] of Object.entries(ret.qty)) {
531	      if (seen[pid] !== q) throw bad(`退货单 ${retId} 商品 ${pid} 的流水数量与记录不一致`);
532	    }
533	    for (const pid of Object.keys(seen)) {
534	      if (ret.qty[pid] === undefined) throw bad(`退货单 ${retId} 的流水含记录中没有的商品 ${pid}`);
535	    }
536	  }
537	
538	  // 冲销退货流水逐项数量必须与原退货单一致
539	  for (const e of store.entries) {
540	    if (e.type !== 'return-rev') continue;
541	    const rev = store.reversals[e.doc];
542	    if (rev === undefined) throw bad(`冲销退货流水引用了不存在的冲销单 ${e.doc}`);
543	    const ret = store.returns[rev.orig];
544	    if (ret === undefined) throw bad(`冲销单 ${e.doc} 指向的退货原单 ${rev.orig} 不存在`);
545	    if (e.arr !== ret.arrId) throw bad(`冲销单 ${e.doc} 流水的原到货单编号与原退货单不一致`);
546	    if (e.po !== ret.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原退货单不一致`);
547	    if (ret.qty[e.product] !== e.qty)
548	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原退货单不一致`);
549	  }
550	
551	  // 退货不变量：同一原到货单的未冲销累计退货不得超过原到货量；
552	  // 有未冲销退货的到货单禁止冲销（已冲销到货的全部退货必须已冲销）
553	  for (const [retId, ret] of Object.entries(store.returns)) {
554	    const retReversed = Object.values(store.reversals).some((r) => r.orig === retId);
555	    if (retReversed) continue;
556	    if (Object.values(store.reversals).some((r) => r.orig === ret.arrId))
557	      throw bad(`到货单 ${ret.arrId} 已整单冲销，但其退货单 ${retId} 未冲销（有未冲销退货的到货单禁止冲销）`);
558	    const arr = store.arrivals[ret.arrId];
559	    const sumByPid = nullProto<Record<string, number>>();
560	    for (const [otherId, other] of Object.entries(store.returns)) {
561	      if (other.arrId !== ret.arrId) continue;
562	      if (Object.values(store.reversals).some((r) => r.orig === otherId)) continue;
563	      for (const [pid, q] of Object.entries(other.qty)) sumByPid[pid] = (sumByPid[pid] ?? 0) + q;
564	    }
565	    for (const [pid, sum] of Object.entries(sumByPid)) {
566	      if (sum > arr.qty[pid])
567	        throw bad(`到货单 ${ret.arrId} 商品 ${pid} 未冲销累计退货 ${sum} 超过原到货量 ${arr.qty[pid]}`);
568	    }
569	  }
570	
571	  // 冲销流水类型必须与原单业务类型一致（入库→in-rev、到货→arrival-rev、退货→return-rev 等）；
572	  // 取消单冲销不产生库存流水（取消本身不改库存），故不要求、也不允许携带流水。
573	  const revIdsWithEntries = nullProto<Record<string, boolean>>();
574	  for (const [revId, rev] of Object.entries(store.reversals)) {
575	    const origDoc = store.docs[rev.orig];
576	    // 原单为取消单时（前面已确认必为库存单/到货单/取消单/退货单之一）不应存在任何冲销流水
577	    let expected: EntryType | undefined;
578	    if (origDoc !== undefined) expected = `${origDoc.content.type}-rev` as EntryType;
579	    else if (store.arrivals[rev.orig] !== undefined) expected = 'arrival-rev';
580	    else if (store.returns[rev.orig] !== undefined) expected = 'return-rev';
581	    for (const e of store.entries) {
582	      if (e.doc !== revId) continue;
583	      if (expected === undefined)
584	        throw bad(`冲销单 ${revId} 冲销的是取消单 ${rev.orig}，不应携带库存流水`);
585	      revIdsWithEntries[revId] = true;
586	      if (e.type !== expected)
587	        throw bad(`冲销单 ${revId} 的流水类型与原单 ${rev.orig} 的业务类型不一致`);
588	    }
589	    if (expected !== undefined) revIdsWithEntries[revId] ??= false;
590	  }
591	  for (const revId of Object.keys(store.reversals)) {
592	    if (revIdsWithEntries[revId] === false) throw bad(`冲销单 ${revId} 缺少冲销流水`);
593	  }
594	
595	  // 采购进度不变量：有效到货 = 未冲销到货 - 未冲销退货；任一商品
596	  // “有效到货 + 未冲销累计取消”不得超过订购量
597	  // （待到货量 = 订购量 - 有效到货量 - 有效取消量，不得为负）。
598	  // 注意：退货释放待到货后允许再次到货，故未冲销到货总量本身可以超过订购量，
599	  // 必须先抵减未冲销退货再校验。
600	  for (const [poId, po] of Object.entries(store.purchases)) {
601	    const arrived = nullProto<Record<string, number>>();
602	    for (const [arrId, arr] of Object.entries(store.arrivals)) {
603	      if (arr.poId !== poId) continue;
604	      const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
605	      if (isReversed) continue; // 已整单冲销的到货不再计入有效到货
606	      for (const [pid, q] of Object.entries(arr.qty)) {
607	        arrived[pid] = (arrived[pid] ?? 0) + q;
608	      }
609	    }
610	    // 未冲销退货抵减有效到货（前面已保证其原到货单未冲销且不超退）
611	    for (const [retId, ret] of Object.entries(store.returns)) {
612	      if (ret.poId !== poId) continue;
613	      const isReversed = Object.values(store.reversals).some((r) => r.orig === retId);
614	      if (isReversed) continue;
615	      for (const [pid, q] of Object.entries(ret.qty)) {
616	        arrived[pid] = (arrived[pid] ?? 0) - q;
617	        if (arrived[pid] < 0)
618	          throw bad(`采购单 ${poId} 商品 ${pid} 未冲销累计退货超过有效到货量`);
619	      }
620	    }
621	    for (const [pid, q] of Object.entries(arrived)) {
622	      if (q > (po.ordered[pid] ?? 0))
623	        throw bad(`采购单 ${poId} 商品 ${pid} 有效到货（未冲销到货减未冲销退货）超过订购量`);
624	    }
625	    const cancelled = nullProto<Record<string, number>>();
626	    for (const [canId, can] of Object.entries(store.cancels)) {
627	      if (can.poId !== poId) continue;
628	      const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
629	      if (isReversed) continue; // 已整单冲销的取消不再计入有效取消
630	      for (const [pid, q] of Object.entries(can.qty)) {
631	        cancelled[pid] = (cancelled[pid] ?? 0) + q;
632	        if ((arrived[pid] ?? 0) + cancelled[pid] > po.ordered[pid])
633	          throw bad(`采购单 ${poId} 商品 ${pid} 有效到货与有效取消合计超过订购量（待到货量为负）`);
634	      }
635	    }
636	  }
637	
638	  return store;
639	}
