641	function saveStore(dataDir: string, store: Store): void {
642	  const path = dataPath(dataDir);
643	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
644	  try {
645	    mkdirSync(dataDir, { recursive: true });
646	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
647	    renameSync(tmp, path);
648	  } catch (e) {
649	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
650	  }
651	}
