653	// ---------- 参数解析 ----------
654	
655	interface ParsedArgs {
656	  positionals: string[];
657	  flags: Record<string, string>;
658	  multi: Record<string, string[]>;
659	}
660	
661	function parseArgs(
662	  tokens: string[],
663	  singles: string[],
664	  multis: string[] = [],
665	): ParsedArgs {
666	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
667	  const singleSet = new Set(singles);
668	  const multiSet = new Set(multis);
669	
670	  for (let i = 0; i < tokens.length; i++) {
671	    const tok = tokens[i];
672	    if (tok.startsWith('--')) {
673	      let key = tok;
674	      let value: string | undefined;
675	      const eq = tok.indexOf('=');
676	      if (eq >= 0) {
677	        key = tok.slice(0, eq);
678	        value = tok.slice(eq + 1);
679	      }
680	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
681	      if (value === undefined) {
682	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
683	        value = tokens[++i];
684	      }
685	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
686	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
687	      else out.flags[key] = value;
688	    } else {
689	      out.positionals.push(tok);
690	    }
691	  }
692	  return out;
693	}
