717	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
718	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
719	  const docId = args.positionals[0];
720	  if (docId === undefined || args.positionals.length !== 1)
721	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
722	
723	  const items = new Map<string, number>();
724	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
725	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
726	
727	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
728	  if (type === 'transfer') {
729	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
730	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
731	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
732	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
733	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
734	  } else {
735	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
736	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
737	  }
738	  return req;
739	}
