741	interface CountItem {
742	  expected: number; // 预期账面量
743	  actual: number; // 实盘量
744	}
745	
746	interface CountRequest {
747	  docId: string;
748	  wh: string;
749	  items: Map<string, CountItem>;
750	}
751	
752	function parseNonNegInt(label: string, raw: string): number {
753	  const s = raw.trim();
754	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
755	  const n = Number(s);
756	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
757	  return n;
758	}
759	
760	function parseCountArgs(tokens: string[]): CountRequest {
761	  const args = parseArgs(tokens, ['--wh'], ['--item']);
762	  const docId = args.positionals[0];
763	  if (docId === undefined || args.positionals.length !== 1)
764	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
765	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
766	
767	  const items = new Map<string, CountItem>();
768	  for (const raw of args.multi['--item'] ?? []) {
769	    const parts = raw.split(':');
770	    if (parts.length !== 3)
771	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
772	    const pid = trimOrThrow('商品编号', parts[0]);
773	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
774	    const actual = parseNonNegInt(`商品 ${pid} 的实盘量`, parts[2]);
775	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
776	    items.set(pid, { expected, actual });
777	  }
778	  if (items.size === 0)
779	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
780	
781	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
782	}
