878	// ---------- 整批导入文件解析 ----------
879	
880	type ImportRequest =
881	  | { kind: 'doc'; req: DocRequest }
882	  | { kind: 'count'; req: CountRequest }
883	  | { kind: 'reverse'; docId: string; orig: string }
884	  | { kind: 'po'; req: PurchaseRequest }
885	  | { kind: 'arrival'; req: ArrivalRequest }
886	  | { kind: 'cancel'; req: CancelRequest }
887	  | { kind: 'return'; req: ReturnRequest };
888	
889	/** 读取导入文件：无法读取属于读写失败（退出 1），不改变任何已提交状态。 */
890	function readImportFile(file: string): string {
891	  try {
892	    return readFileSync(file, 'utf8');
893	  } catch (e) {
894	    throw new DataError(`无法读取导入文件 ${file}：${(e as Error).message}（不会改变任何已提交数据）`);
895	  }
896	}
897	
898	/**
899	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
900	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
901	 */
902	function parseImportFile(raw: string): ImportRequest[] {
903	  let data: unknown;
904	  try {
905	    data = JSON.parse(raw);
906	  } catch (e) {
907	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
908	  }
909	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
910	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
911	
912	  const out: ImportRequest[] = [];
913	  // 顶层位置一律标注 1 起序号，便于纠正
914	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
915	
916	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
917	    const v = obj[key];
918	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
919	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
920	    const s = v.trim();
921	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
922	    return s;
923	  };
924	
925	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
926	    for (const k of Object.keys(obj)) {
927	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
928	    }
929	  };
930	
931	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
932	    const v = obj.items;
933	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
934	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
935	    if (v.length === 0) throw at(i, '商品明细至少一项');
936	    const merged = new Map<string, number>();
937	    v.forEach((entry, j) => {
938	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
939	      const e = entry as Record<string, unknown>;
940	      checkUnknown(e, ['product', 'qty'], i);
941	      const pid = e.product;
942	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
943	      const p = pid.trim();
944	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
945	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
946	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
947	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
948	      merged.set(p, sum);
949	    });
950	    return merged;
951	  };
952	
953	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
954	    const v = obj.items;
955	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
956	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
957	    if (v.length === 0) throw at(i, '商品明细至少一项');
958	    const items = new Map<string, CountItem>();
959	    v.forEach((entry, j) => {
960	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
961	      const e = entry as Record<string, unknown>;
962	      checkUnknown(e, ['product', 'expected', 'actual'], i);
963	      const pid = e.product;
964	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
965	      const p = pid.trim();
966	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
967	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
968	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
969	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
970	      items.set(p, { expected: e.expected, actual: e.actual });
971	    });
972	    return items;
973	  };
974	
975	  data.forEach((rawItem, i) => {
976	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
977	    const item = rawItem as Record<string, unknown>;
978	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
979	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
980	
981	    switch (item.type) {
982	      case 'in':
983	      case 'out': {
984	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
985	        const docId = requireString(item, 'id', '单据编号', i);
986	        const wh = requireString(item, 'wh', '仓库标识', i);
987	        out.push({ kind: 'doc', req: { type: item.type, docId, wh, items: parseQtyItems(item, i) } });
988	        break;
989	      }
990	      case 'transfer': {
991	        checkUnknown(item, ['type', 'id', 'from', 'to', 'items'], i);
992	        const docId = requireString(item, 'id', '单据编号', i);
993	        const from = requireString(item, 'from', '调出仓标识', i);
994	        const to = requireString(item, 'to', '调入仓标识', i);
995	        if (from === to) throw at(i, '调拨单的调出仓与调入仓不能相同');
996	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
997	        break;
998	      }
999	      case 'count': {
1000	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1001	        const docId = requireString(item, 'id', '单据编号', i);
1002	        const wh = requireString(item, 'wh', '仓库标识', i);
1003	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
1004	        break;
1005	      }
1006	      case 'reverse': {
1007	        checkUnknown(item, ['type', 'id', 'orig'], i);
1008	        const docId = requireString(item, 'id', '冲销单编号', i);
1009	        const orig = requireString(item, 'orig', '原单编号', i);
1010	        out.push({ kind: 'reverse', docId, orig });
1011	        break;
1012	      }
1013	      case 'po': {
1014	        checkUnknown(item, ['type', 'id', 'supplier', 'wh', 'items'], i);
1015	        const poId = requireString(item, 'id', '采购编号', i);
1016	        const supplier = requireString(item, 'supplier', '供应商名称', i);
1017	        const wh = requireString(item, 'wh', '收货仓标识', i);
1018	        out.push({ kind: 'po', req: { poId, supplier, wh, items: parseQtyItems(item, i) } });
1019	        break;
1020	      }
1021	      case 'arrival': {
1022	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1023	        const arrId = requireString(item, 'id', '到货单编号', i);
1024	        const poId = requireString(item, 'po', '采购编号', i);
1025	        out.push({ kind: 'arrival', req: { arrId, poId, items: parseQtyItems(item, i) } });
1026	        break;
1027	      }
1028	      case 'cancel': {
1029	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1030	        const canId = requireString(item, 'id', '取消单编号', i);
1031	        const poId = requireString(item, 'po', '采购编号', i);
1032	        out.push({ kind: 'cancel', req: { canId, poId, items: parseQtyItems(item, i) } });
1033	        break;
1034	      }
1035	      case 'return': {
1036	        checkUnknown(item, ['type', 'id', 'arrival', 'items'], i);
1037	        const retId = requireString(item, 'id', '退货单编号', i);
1038	        const arrId = requireString(item, 'arrival', '原到货单编号', i);
1039	        out.push({ kind: 'return', req: { retId, arrId, items: parseQtyItems(item, i) } });
1040	        break;
1041	      }
1042	      default:
1043	        throw at(i, `不支持的业务类型 "${String(item.type)}"，只允许 in、out、transfer、count、reverse、po、arrival、cancel、return`);
1044	    }
1045	  });
1046	
1047	  return out;
1048	}
