1050	// ---------- 业务核心 ----------
1051	
1052	const MAX_SAFE = Number.MAX_SAFE_INTEGER;
1053	
1054	/** 带符号数量文本：正数加 +，负数保留 -，零为 0。 */
1055	function fmtSigned(n: number): string {
1056	  return n > 0 ? `+${n}` : String(n);
1057	}
1058	
1059	function canonicalContent(req: DocRequest): Record<string, unknown> {
1060	  const items: Record<string, number> = nullProto();
1061	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
1062	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
1063	  return { type: req.type, wh: req.wh!, items };
1064	}
1065	
1066	function getStock(stock: Store['stock'], pid: string, wh: string): number {
1067	  return stock[pid]?.[wh] ?? 0;
1068	}
1069	
1070	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
1071	  (stock[pid] ??= nullProto<Record<string, number>>())[wh] = qty;
1072	}
1073	
1074	/**
1075	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
1076	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
1077	 */
1078	function cloneStock(stock: Store['stock']): Store['stock'] {
1079	  const out = nullProto<Store['stock']>();
1080	  for (const pid of Object.keys(stock)) {
1081	    const whMap = nullProto<Record<string, number>>();
1082	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
1083	    out[pid] = whMap;
1084	  }
1085	  return out;
1086	}
1087	
1088	function canonicalCountContent(req: CountRequest): Record<string, unknown> {
1089	  const items: Record<string, unknown> = nullProto();
1090	  for (const pid of [...req.items.keys()].sort()) {
1091	    const it = req.items.get(pid)!;
1092	    items[pid] = { expected: it.expected, actual: it.actual };
1093	  }
1094	  return { type: 'count', wh: req.wh, items };
1095	}
1096	
1097	/** 采购单规范化内容：明细按商品编号排序，比较时与明细顺序无关。 */
1098	function canonicalPurchaseContent(req: PurchaseRequest): {
1099	  supplier: string;
1100	  wh: string;
1101	  ordered: Record<string, number>;
1102	} {
1103	  const ordered: Record<string, number> = nullProto();
1104	  for (const pid of [...req.items.keys()].sort()) ordered[pid] = req.items.get(pid)!;
1105	  return { supplier: req.supplier, wh: req.wh, ordered };
1106	}
1107	
1108	/** 到货明细规范化：合并后数量按商品编号排序。 */
1109	function canonicalArrivalItems(items: Map<string, number>): Record<string, number> {
1110	  const out: Record<string, number> = nullProto();
1111	  for (const pid of [...items.keys()].sort()) out[pid] = items.get(pid)!;
1112	  return out;
1113	}
1114	
1115	interface ApplyOutcome {
1116	  duplicate: boolean;
1117	  header: string; // 结果首行汇总
1118	  lines: string[]; // 逐项明细结果
