1215	  /** 计算某采购单各商品当前“有效到货”：未冲销累计到货 - 未冲销累计退货。 */
1216	  private effectiveArrived(poId: string): Record<string, number> {
1217	    const arrived = nullProto<Record<string, number>>();
1218	    for (const [arrId, arr] of Object.entries(this.arrivals)) {
1219	      if (arr.poId !== poId || this.reversedOrigs.has(arrId)) continue;
1220	      for (const [pid, q] of Object.entries(arr.qty)) arrived[pid] = (arrived[pid] ?? 0) + q;
