1223	    for (const [retId, ret] of Object.entries(this.returns)) {
1224	      if (ret.poId !== poId || this.reversedOrigs.has(retId)) continue;
1225	      for (const [pid, q] of Object.entries(ret.qty)) arrived[pid] = (arrived[pid] ?? 0) - q;
1226	    }
1227	    return arrived;
1228	  }
