1471	   * 原收货仓当前余量扣减；超退、缺货或明细非法整单拒绝、不占编号。
1472	   * 退货抵减有效到货（有效到货 = 未冲销到货 - 未冲销退货），相应数量重新待到货、
1473	   * 等待补收；不改订购与取消。退货单与库存/到货/取消/冲销单共用唯一编号空间。
1474	   * 同号同原到货同合并数量重放返回原结果——即使进度已变化、该退货或原到货已
1475	   * 冲销也不再校验、不再生效；同号不同内容或其他业务拒绝。
1476	   */
1477	  applyReturn(req: ReturnRequest): ApplyOutcome {
1478	    const existed = this.returns[req.retId];
1479	    if (existed !== undefined) {
1480	      if (
1481	        existed.arrId !== req.arrId ||
1482	        stableStringify(existed.qty) !== stableStringify(canonicalArrivalItems(req.items))
1483	      )
1484	        throw new BizError(`退货单编号 ${req.retId} 已用于内容不同的单据，拒绝提交`);
1485	      return {
1486	        duplicate: true,
1487	        header: this.returnHeader(req.retId, existed),
1488	        lines: existed.resultLines,
1489	        repeatedFrom: this.repeatedReturnSource(req.retId),
1490	      };
1491	    }
1492	    // 与入库/出库/调拨/盘点/到货/取消/冲销单共用唯一编号空间（采购单编号空间独立，不在此列）
1493	    if (this.docs[req.retId] !== undefined)
1494	      throw new BizError(`单据编号 ${req.retId} 已用于入库/出库/调拨/盘点单，拒绝提交`);
1495	    if (this.arrivals[req.retId] !== undefined)
1496	      throw new BizError(`单据编号 ${req.retId} 已用于到货单，拒绝提交`);
1497	    if (this.cancels[req.retId] !== undefined)
1498	      throw new BizError(`单据编号 ${req.retId} 已用于取消单，拒绝提交`);
1499	    if (this.revs[req.retId] !== undefined)
1500	      throw new BizError(`单据编号 ${req.retId} 已用于冲销单，拒绝提交`);
1501	
1502	    const arr = this.arrivals[req.arrId];
1503	    if (arr === undefined) throw new BizError(`原到货单 ${req.arrId} 不存在，拒绝退货`);
1504	    if (this.reversedOrigs.has(req.arrId))
1505	      throw new BizError(`原到货单 ${req.arrId} 已整单冲销，不能再对其退货，拒绝整单`);
1506	
1507	    const poId = arr.poId;
1508	    const wh = arr.wh;
1509	    const po = this.pos[poId];
1510	    const pids = [...req.items.keys()].sort();
