1513	    const returnedBefore = nullProto<Record<string, number>>();
1514	    for (const [retId, ret] of Object.entries(this.returns)) {
1515	      if (ret.arrId !== req.arrId || this.reversedOrigs.has(retId)) continue;
1516	      for (const [pid, q] of Object.entries(ret.qty)) returnedBefore[pid] = (returnedBefore[pid] ?? 0) + q;
1517	    }
1518	    const arrivedEff = this.effectiveArrived(poId); // 有效到货（未冲销到货 - 未冲销退货）
1519	    const cancelled = this.effectiveCancelled(poId); // 未冲销累计取消
