2173	function formatEntry(e: LedgerEntry): string {
2174	  let line: string;
2175	  if (e.type === 'count' || e.type === 'count-rev') {
2176	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
2177	    line =
2178	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
2179	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
2180	  } else {
2181	    let signed: string;
2182	    // 符号必须与前后余量一致：入库/冲销出库/到货/冲销退货/调入方向为增，其余为减
2183	    const increases =
2184	      e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev' ||
2185	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
2186	        (e.type === 'transfer') === (e.wh === e.to));
2187	    signed = `${increases ? '+' : '-'}${e.qty}`;
2188	    line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
2189	    if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
2190	    if (e.po !== undefined) line += `\t采购单=${e.po}`;
2191	    if (e.arr !== undefined) line += `\t原到货单=${e.arr}`;
2192	  }
2193	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
2194	  return line;
2195	}
