2250	/** 计算采购单各商品的有效到货（未冲销到货-未冲销退货）、有效退货、有效取消与待到货量。 */
2251	function purchaseProgress(store: Store, poId: string): {
2252	  effective: Record<string, number>;
2253	  returned: Record<string, number>;
2254	  cancelled: Record<string, number>;
2255	  remaining: Record<string, number>;
2256	} {
2257	  const effective = nullProto<Record<string, number>>();
2258	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
2259	    if (arr.poId !== poId) continue;
2260	    const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
2261	    if (isReversed) continue;
2262	    for (const [pid, q] of Object.entries(arr.qty)) effective[pid] = (effective[pid] ?? 0) + q;
2263	  }
2264	  const returned = nullProto<Record<string, number>>();
2265	  for (const [retId, ret] of Object.entries(store.returns)) {
2266	    if (ret.poId !== poId) continue;
2267	    const isReversed = Object.values(store.reversals).some((r) => r.orig === retId);
2268	    if (isReversed) continue;
2269	    for (const [pid, q] of Object.entries(ret.qty)) {
2270	      returned[pid] = (returned[pid] ?? 0) + q;
2271	      effective[pid] = (effective[pid] ?? 0) - q; // 未冲销退货抵减有效到货
2272	    }
2273	  }
2274	  const cancelled = nullProto<Record<string, number>>();
2275	  for (const [canId, can] of Object.entries(store.cancels)) {
2276	    if (can.poId !== poId) continue;
2277	    const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
2278	    if (isReversed) continue;
2279	    for (const [pid, q] of Object.entries(can.qty)) cancelled[pid] = (cancelled[pid] ?? 0) + q;
2280	  }
2281	  const po = store.purchases[poId];
2282	  const remaining = nullProto<Record<string, number>>();
2283	  for (const [pid, ordered] of Object.entries(po.ordered)) {
2284	    remaining[pid] = ordered - (effective[pid] ?? 0) - (cancelled[pid] ?? 0);
2285	  }
2286	  return { effective, returned, cancelled, remaining };
2287	}
