2289	/**
2290	 * 单商品采购状态。无取消时保持原有展示（未到货/部分到货/收齐）；
2291	 * 有取消时区分仍待收与已结清：待到货为零但含取消的结清不报“收齐”，
2292	 * 取消永远不计作到货。
2293	 */
2294	function poStatus(ordered: number, effective: number, cancelled = 0): string {
2295	  const remaining = ordered - effective - cancelled;
2296	  if (cancelled === 0) {
