2508	/**
2509	 * 整批导入：按列表顺序在同一份草稿上处理各项，后项可见前项生效结果；
2510	 * 任一项失败整批拒绝（此前已保存的单据不撤销，本批任何变动均不落库）。
2511	 * 全部重复时不改写数据。逐项输出编号、首次生效/重复（及重复来源）状态与提交结果。
2512	 */
2513	function runImport(rest: string[], dataDir: string): void {
2514	  const args = parseArgs(rest, ['--file']);
2515	  const file = args.flags['--file'];
2516	  if (file === undefined || args.positionals.length > 0)
2517	    throw new UsageError('用法：import --file <单据列表 JSON 文件>');
2518	
2519	  // 先完整读取并解析文件：文件不可读/解析失败时绝不触碰已提交状态
2520	  const requests = parseImportFile(readImportFile(file));
2521	
2522	  // 参数与文件格式均确认无误后才打开本地数据；损坏数据在此被拒绝且不报告成功
2523	  const store = loadStore(dataDir);
2524	  const ledger = new Ledger(store);
2525	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
2526	  const blocks: string[] = [];
2527	  let newCount = 0;
2528	
2529	  requests.forEach((r, i) => {
2530	    const pos = `第 ${i + 1}/${requests.length} 项`;
2531	    // 模拟阶段的业务拒绝同样标注列表位置与原因
2532	    const apply = (): ApplyOutcome => {
2533	      switch (r.kind) {
2534	        case 'doc': return ledger.applyDoc(r.req);
2535	        case 'count': return ledger.applyCount(r.req);
2536	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
2537	        case 'po': return ledger.applyPurchase(r.req);
2538	        case 'arrival': return ledger.applyArrival(r.req);
2539	        case 'cancel': return ledger.applyCancel(r.req);
2540	        case 'return': return ledger.applyReturn(r.req);
2541	      }
2542	    };
2543	    let outcome: ApplyOutcome;
2544	    try {
2545	      outcome = apply();
2546	    } catch (e) {
2547	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
2548	      throw e;
2549	    }
2550	    const id =
2551	      r.kind === 'reverse' ? r.docId
2552	      : r.kind === 'po' ? r.req.poId
2553	      : r.kind === 'arrival' ? r.req.arrId
2554	      : r.kind === 'cancel' ? r.req.canId
2555	      : r.kind === 'return' ? r.req.retId
2556	      : r.req.docId;
2557	
2558	    let status: string;
2559	    if (outcome.duplicate) {
2560	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
2561	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
2562	    } else {
2563	      status = '首次生效';
2564	      newCount++;
2565	    }
2566	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
2567	  });
2568	
2569	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
2570	  ledger.commit(dataDir);
2571	
2572	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
2573	  for (const block of blocks) console.log(block);
2574	}
