2728	  // 先抽出全局 -d/--data，其余按命令解析
2729	  let dataDir = DEFAULT_DATA_DIR;
2730	  const rest: string[] = [];
2731	  for (let i = 0; i < argv.length; i++) {
2732	    const t = argv[i];
2733	    if (t === '-d' || t === '--data') {
2734	      if (i + 1 >= argv.length) throw new UsageError(`参数 ${t} 缺少数据目录取值`);
2735	      dataDir = argv[++i];
2736	    } else if (t.startsWith('--data=')) {
2737	      dataDir = t.slice('--data='.length);
2738	    } else {
2739	      rest.push(t);
2740	    }
2741	  }
2742	
2743	  if (rest.length === 0) {
2744	    printHelp();
2745	    return;
2746	  }
2747	  const cmd = rest[0];
2748	  if ((cmd === '-h' || cmd === '--help') && rest.length === 1) {
2749	    printHelp();
2750	    return;
2751	  }
2752	
2753	  const tokens = rest.slice(1);
2754	  switch (cmd) {
2755	    case 'product': {
2756	      const store = loadStore(dataDir);
2757	      runProduct(tokens, dataDir, store);
2758	      break;
2759	    }
2760	    case 'in':
2761	    case 'out':
2762	    case 'transfer': {
2763	      const req = parseDocArgs(cmd, tokens);
2764	      const store = loadStore(dataDir);
2765	      const ledger = new Ledger(store);
2766	      const outcome = ledger.applyDoc(req);
2767	      ledger.commit(dataDir);
2768	      if (outcome.duplicate) {
2769	        console.log(`单据 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
2770	      } else {
2771	        console.log(outcome.header);
2772	      }
2773	      for (const line of outcome.lines) console.log(line);
2774	      break;
2775	    }
2776	    case 'count': {
2777	      const req = parseCountArgs(tokens);
2778	      const store = loadStore(dataDir);
2779	      const ledger = new Ledger(store);
2780	      const outcome = ledger.applyCount(req);
2781	      ledger.commit(dataDir);
2782	      if (outcome.duplicate) {
2783	        console.log(`盘点单 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
2784	      } else {
2785	        console.log(outcome.header);
2786	      }
2787	      for (const line of outcome.lines) console.log(line);
2788	      break;
2789	    }
2790	    case 'reverse': {
2791	      const store = loadStore(dataDir);
2792	      runReverse(tokens, dataDir, store);
2793	      break;
2794	    }
2795	    case 'po': {
2796	      const store = loadStore(dataDir);
2797	      runPo(tokens, dataDir, store);
2798	      break;
2799	    }
2800	    case 'arrival': {
2801	      const store = loadStore(dataDir);
2802	      runArrival(tokens, dataDir, store);
2803	      break;
2804	    }
2805	    case 'cancel': {
2806	      const store = loadStore(dataDir);
2807	      runCancel(tokens, dataDir, store);
2808	      break;
2809	    }
2810	    case 'return': {
2811	      const store = loadStore(dataDir);
2812	      runReturn(tokens, dataDir, store);
2813	      break;
2814	    }
2815	    case 'import': {
2816	      runImport(tokens, dataDir);
2817	      break;
2818	    }
2819	    case 'balance': {
2820	      const store = loadStore(dataDir);
2821	      runBalance(tokens, store);
2822	      break;
2823	    }
2824	    case 'flow': {
