2826	      runFlow(tokens, store);
2827	      break;
2828	    }
2829	    default:
2830	      throw new UsageError(`未知命令：${cmd}（使用 --help 查看可用命令）`);
2831	  }
2832	}
2833	
2834	try {
2835	  run(process.argv.slice(2));
2836	} catch (e) {
2837	  if (e instanceof UsageError) {
2838	    console.error(`${APP_NAME}: ${e.message}`);
2839	    process.exit(2);
2840	  }
2841	  if (e instanceof BizError || e instanceof DataError) {
2842	    console.error(`${APP_NAME}: ${e.message}`);
2843	    process.exit(1);
